<?php
require_once dirname(__DIR__).'/autoload.php';
use LLM\MemoryRecallText;
use LLM\MemoryRecallBlock;
$fail=0;
function selectionCheck(bool $ok,string $label):void {global $fail;echo($ok?'[OK] ':'[FAIL] ').$label."\n";if(!$ok)$fail++;}
selectionCheck(MemoryRecallText::roots('трёхлитрового попугая')===['трехлитров','попуг']&&MemoryRecallText::roots('трехлитровый попугай')===['трехлитров','попуга'],'recall uses official Snowball roots, including its asymmetric parrot forms');
selectionCheck(MemoryRecallText::roots('Альфарием')===MemoryRecallText::roots('Альфарий'),'instrumental and nominative forms match');
selectionCheck(MemoryRecallText::boolean('трёхлитрового попугая',true)==='+трехлитров* +попуг*','strong FULLTEXT uses bounded required prefixes');
selectionCheck(MemoryRecallText::identifiers('помнишь DL-6?')===['dl-6'],'structured identifier stays intact');
selectionCheck(MemoryRecallText::matches('DL-60',MemoryRecallText::roots('DL-6'))===[],'identifier does not match a longer identifier');
selectionCheck(MemoryRecallText::boolean('>Феникс <Райт +"')===MemoryRecallText::boolean('Феникс Райт'),'BOOLEAN operators never enter query terms');
selectionCheck(MemoryRecallText::roots('сколько будет два плюс два')===[],'generic arithmetic is not lexical evidence for historical recall');
selectionCheck(MemoryRecallText::matches('пони Лира',MemoryRecallText::roots('Лиру'))!==[],'a bot name used as the topic remains searchable');
selectionCheck(MemoryRecallText::roots('Откуда взялась шутка о трехлитровом попугае?')===MemoryRecallText::roots('трехлитровом попугае'),'question framing does not become mandatory topic evidence');
selectionCheck(MemoryRecallText::roots('Какие были разговоры о горе Эверхуф?')===MemoryRecallText::roots('гора Эверхуф'),'question and conversation framing leave the mountain topic');
selectionCheck(MemoryRecallText::roots('помнишь расскажи пожалуйста что где когда почему откуда какой какая какие каким говорили попугая')===MemoryRecallText::roots('попугая'),'frame words do not consume the twelve-topic limit');
selectionCheck(MemoryRecallText::roots('Что говорили про третью банку?')===MemoryRecallText::roots('третья банка'),'short noun inflections share the same topic roots');
foreach(['банка','банку','банкой','банки']as$form)selectionCheck(MemoryRecallText::matches($form,MemoryRecallText::roots('банку'))!==[],'short noun matches inflection '.$form);
foreach(['конь','коня','коню']as$form)selectionCheck(MemoryRecallText::matches($form,MemoryRecallText::roots('коня'))!==[],'short noun preserves the nominative soft sign '.$form);
foreach(['попугай','попугае','попугаем']as$form)selectionCheck(MemoryRecallText::matches('попугай',MemoryRecallText::roots($form))!==[],'exact Snowball stems match the compatible parrot form '.$form);
selectionCheck(MemoryRecallText::roots('«Откуда?»')===['откуд']&&MemoryRecallText::roots('"Откуда?"')===['откуд']&&MemoryRecallText::roots('Откуда?')===['откуд'],'F3-R3 quoted and standalone content words remain topics');
selectionCheck(MemoryRecallText::roots(MemoryRecallText::queryText('"Что?"',''))===['что'],'quoted topic survives the embedding query cleaner');
selectionCheck(MemoryRecallText::matches('дом и домом',MemoryRecallText::roots('дому'))!==[]&&MemoryRecallText::matches('домино',MemoryRecallText::roots('дому'))===[],'F3-R5 confirms equality of stems rather than SQL prefix similarity');
$idfRoots=['пальц','люд','копыт','пон'];$idfWeights=['пальц'=>4.0,'люд'=>0.5,'копыт'=>0.5,'пон'=>0.2];
selectionCheck(MemoryRecallText::score(1,$idfRoots,$idfWeights)>MemoryRecallText::score(14,$idfRoots,$idfWeights),'F3-R4 rare subject outweighs three common stems');
$weightedWindow=MemoryRecallText::window([['source'=>'chat:1','text'=>'Люди и пони топали копытами'],['source'=>'chat:2','text'=>'Ловкие пальцы']], 'пальцы люди копыта пони',$idfWeights);
selectionCheck($weightedWindow[0]['source']==='chat:2','F3-R4 source window uses the same rarity weights');
foreach(['банкир','банкомат','банкрот','банкет','бантик','город','горечь','судьба','котик','мастерские','попугательство','DL-60']as$word){
 $query=match($word){'город','горечь'=>'горе','судьба'=>'суде','котик'=>'коты','мастерские'=>'мастер','попугательство'=>'попугая','DL-60'=>'DL-6',default=>'банку'};
 selectionCheck(MemoryRecallText::matches($word,MemoryRecallText::roots($query))===[],'short inflection does not merge unrelated word '.$word);
}
selectionCheck(!LLM\MemoryRetriever::candidateAllowed(0.42319553,0,3,true),'mixed recall excludes the observed vector-only false candidate');
selectionCheck(LLM\MemoryRetriever::candidateAllowed(0.6,0,3,true),'mixed recall retains sufficiently strong vector-only candidates');
selectionCheck(!LLM\MemoryRetriever::candidateAllowed(0.4794,0,3,true),'mixed recall rejects the observed off-topic semantic fallback');
selectionCheck(LLM\MemoryRetriever::candidateAllowed(0.3,3,3,true),'complete topic evidence retains lower cosine');
selectionCheck(!LLM\MemoryRetriever::candidateAllowed(0.3,1,3,true),'one generic root does not lower the partial-topic cosine floor');
selectionCheck(LLM\MemoryRetriever::candidateAllowed(0.3,7,15,true),'three of four grounded topics can retain low cosine');
selectionCheck(!LLM\MemoryRetriever::candidateAllowed(0.3,3,15,true),'two generic roots out of four do not admit low cosine');
selectionCheck(LLM\MemoryRetriever::candidateAllowed(0.3,1,3,true,false,3),'a source topic plus complete association support retains a cultural query');
selectionCheck(!LLM\MemoryRetriever::candidateAllowed(0.3,0,3,true,false,3),'associations alone cannot lower the vector-only threshold');
selectionCheck(LLM\MemoryRetriever::candidateAllowed(0.3,0,3,false,false,3),'complete associations preserve the legacy fallback when no grounded alternative exists');
$lines=[];for($i=1;$i<=15;$i++)$lines[]=['source'=>'chat:'.$i,'author'=>'Другой','user_id'=>9,'role'=>'user','date_utc'=>'2026-11-01','text'=>'Соседняя реплика номер '.$i];
$lines[10]['text']='А вот и трёхлитровый попугай из дела DL-6';
$episode=['id'=>7,'date'=>'2026-11-01','source_ids'=>array_column($lines,'source'),'lines'=>$lines];
$window=MemoryRecallText::window($lines,'расскажи про трёхлитрового попугая');
selectionCheck($window[0]['source']==='chat:11','matching source deep in episode is first');
selectionCheck(in_array('chat:10',array_column($window,'source'),true)&&in_array('chat:12',array_column($window,'source'),true),'window retains neighboring turns');
$context=[['role'=>'user','content'=>LLM\LyraMemory::BLOCK_MARKER.' заметки'],['role'=>'user','chat_message_id'=>22,'content'=>'Вопрос']];
$out=MemoryRecallBlock::apply($context,[$episode],8000,'трёхлитрового попугая');
$background=current(array_filter($out,fn($r)=>str_starts_with($r['content'],MemoryRecallBlock::MARKER)));
selectionCheck(str_contains($background['content'],'трёхлитровый попугай')&&str_contains($background['content'],'chat:11'),'background shows matching words with source attribution');
selectionCheck(str_contains(end($out)['content'],'трёхлитровый попугай')&&str_contains(end($out)['content'],'chat:11'),'focus shows the same match instead of episode head');
selectionCheck($out[2]===$context[1],'question history is byte-identical');
$long=$lines;$long[10]['text']=str_repeat('начало ',180).'DL-6 решился благодаря попугаю '.str_repeat('конец ',100);
$out=MemoryRecallBlock::apply($context,[array_replace($episode,['lines'=>$long])],8000,'DL-6');
selectionCheck(str_contains(end($out)['content'],'DL-6'),'match deep inside a long turn remains visible in focus');
$dense=[array_replace($lines[0],['text'=>'Старые игры. '.str_repeat('другое начало ',100).'Симуляторы подводных лодок были отдельной темой.'])];
$denseWindow=MemoryRecallText::window($dense,'старые симуляторы подводных лодок');
selectionCheck(str_contains($denseWindow[0]['text'],'Симуляторы подводных лодок'),'excerpt selects the denser topical span instead of the first generic root');
$roleWindow=MemoryRecallText::window([array_replace($lines[0],['text'=>'Обсуждали ДнД']),array_replace($lines[1],['text'=>'Другой разговор']),array_replace($lines[2],['text'=>'Ты наш мастер'])],'мастер ДнД');
selectionCheck($roleWindow[0]['source']===$lines[2]['source'],'equally matched turns prefer the leading topic over an incidental later topic');
selectionCheck(MemoryRecallText::window($lines,'совершенно другая тема')===$lines,'no lexical anchor preserves original source order without external calls');
$memory=array_filter($out,fn($r)=>str_starts_with($r['content'],LLM\LyraMemory::BLOCK_MARKER)||str_starts_with($r['content'],MemoryRecallBlock::MARKER)||str_starts_with($r['content'],MemoryRecallBlock::FOCUS));
selectionCheck(array_sum(array_map(fn($r)=>mb_strlen($r['content']),$memory))<=8000,'shared block budget still includes headers and focus');
selectionCheck(LLM\MemoryRetriever::MIN_COSINE>0.3954,'chat-calibrated vector-only threshold rejects observed weak false match');
echo $fail?"FAIL: $fail\n":"ALL PASS\n";exit($fail?1:0);
